type Feature = {
  title: string;
  desc: ReactNode;
  icon: ReactNode;
  wide: boolean;
  note?: string;
};

const ROW1: Feature[] = [
  {
    title: "매출의 50% 보장",
    desc: (
      <>
        1인 프리랜서 운영으로 줄인 인건비,
        <br />
        매출 수수료로 보장해드려요.
      </>
    ),
    icon: <IconMoney />,
    wide: true,
  },
  {
    title: "매출 압박 없이 자유롭게",
    desc: (
      <>
        하는 만큼 나오는 매출, 압박이나
        <br />
        야근 없이 자유롭게 꿈을 펼쳐보세요.
      </>
    ),
    icon: <IconCalendarCheck />,
    wide: false,
  },
];

const ROW2: Feature[] = [
  {
    title: "조직 컨설팅",
    desc: (
      <>
        조직 운영을 희망 시, 조직 운영을
        <br />
        위한 컨설팅도 진행해드려요.
      </>
    ),
    icon: <IconOrg />,
    wide: false,
  },
  {
    title: "개별 CRM 제공",
    desc: (
      <>
        처음이여도 편리하게 시작해보세요.
        <br />
        에듀바이저 1인당 개별 CRM* 서비스를 제공합니다.
      </>
    ),
    icon: <IconMonitor />,
    wide: true,
    note: "*CRM : 학습자 신규, 가망관리, 매출파일 기입을 한 홈페이지에서!",
  },
];

function Card({ feature }: { feature: Feature }) {
  return (
    <div className={`${styles.card} ${feature.wide ? styles.wide : styles.fixed}`}>
      <div className={styles.cardText}>
        {feature.note ? (
          <>
            <div className={styles.textTop}>
              <h3 className={styles.cardTitle}>{feature.title}</h3>
              <p className={styles.cardDesc}>{feature.desc}</p>
            </div>
            <span className={styles.note}>{feature.note}</span>
          </>
        ) : (
          <>
            <h3 className={styles.cardTitle}>{feature.title}</h3>
            <p className={styles.cardDesc}>{feature.desc}</p>
          </>
        )}
      </div>
      <span className={styles.cardIcon}>{feature.icon}</span>
    </div>
  );
}

/**
 * 메인 - "한평생 에듀바이저스가 교육전문가를 지원합니다" 섹션
 */
export default function SupportSection() {
  return (
    <section className={styles.section}>
      <div className={styles.header}>
        <h2 className={styles.title}>
          한평생 에듀바이저스가
          <br />
          교육전문가를 지원합니다
        </h2>
        <p className={styles.subtitle}>
          교육 전문가가 최고의 성과를 낼 수 있도록, 모든 과정을 함께하겠습니다.
        </p>
      </div>

      <div className={styles.cards}>
        <div className={styles.row}>
          {ROW1.map((f) => (
            <Card key={f.title} feature={f} />
          ))}
        </div>
        <div className={styles.row}>
          {ROW2.map((f) => (
            <Card key={f.title} feature={f} />
          ))}
        </div>
      </div>
    </section>
  );
}
